/**
 * Everything this app is built from, and what each piece is licensed under.
 *
 * Two sources, because there are two kinds of dependency and only one of them can be discovered
 * automatically. The npm tree is generated by scripts/generate-attributions.mjs, which reads what
 * actually ships rather than what someone remembered to write down. Native components are listed
 * here by hand: sherpa-onnx, espeak-ng, ffmpeg and the rest arrive through Gradle or a build
 * script, so nothing can enumerate them from a package manifest.
 *
 * A hand-maintained list is the part that rots, so this one carries its own honesty flag. Where a
 * licence has not actually been confirmed against the shipped artefact it says so, and the screen
 * shows that rather than a confident guess. An attribution list that quietly invents licences is
 * worse than none, because it looks like the question was settled.
 */

export interface AttributedPackage {
  name: string;
  version: string;
  license: string;
  repository?: string;
}

export interface AttributionData {
  packageCount: number;
  packages: AttributedPackage[];
  licenseTexts: Record<string, string>;
  notices: Record<string, string>;
}

export interface NativeComponent {
  name: string;
  license: string;
  /** What it does here, in a sentence someone who did not write the build can follow. */
  role: string;
  url: string;
  /**
   * False when the licence above has not been checked against the artefact that actually ships.
   * Shown in the app, because an unverified claim presented as fact is the failure this list is
   * meant to prevent.
   */
  verified: boolean;
  /** Which builds contain it. Cast ships only in the Play build; the F-Droid build omits it. */
  flavour?: 'gplay' | 'foss' | 'both';
  note?: string;
}

