/**
 * Load the generated npm list.
 *
 * Imported on demand because it is about a hundred kilobytes of licence text that almost nobody
 * opens. A static import would put all of it in the startup path of a phone app whose first screen
 * is a music library, for a screen most people will never visit.
 */
export async function loadAttributions(): Promise<AttributionData> {
  const data = await import('./generated/attributions.json');
  return (data.default ?? data) as unknown as AttributionData;
}

export interface LicenceGroup {
  license: string;
  packages: AttributedPackage[];
}

/**
 * Group packages by licence, commonest first.
 *
 * Four hundred names in one alphabetical column tells a reader nothing. Grouped, the shape of the
 * answer is visible immediately: overwhelmingly MIT, a handful of Apache, and then the few worth
 * actually looking at.
 */
export function groupByLicence(packages: AttributedPackage[]): LicenceGroup[] {
  const groups = new Map<string, AttributedPackage[]>();
  for (const pkg of packages) {
    const key = pkg.license || 'UNKNOWN';
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(pkg);
  }
  return [...groups.entries()]
    .map(([license, list]) => ({
      license,
      packages: [...list].sort((a, b) => a.name.localeCompare(b.name)),
    }))
    .sort((a, b) => b.packages.length - a.packages.length || a.license.localeCompare(b.license));
}

/**
 * Components whose licence is not actually settled.
 *
 * Surfaced rather than buried. These are the entries that need a person to go and check something,
 * and a list that hides them is a list that will still be wrong next year.
 */
export function unresolvedComponents(
  components: NativeComponent[] = NATIVE_COMPONENTS,
): NativeComponent[] {
  return components.filter((component) => !component.verified);
}

/** Packages that declare no licence at all, which is a different problem from an unusual one. */
export function undeclaredPackages(packages: AttributedPackage[]): AttributedPackage[] {
  return packages.filter((pkg) => !pkg.license || pkg.license === 'UNKNOWN');
}
